import React, { useEffect, useState } from "react";
import { API } from "../api";
import CountUp from "react-countup";
import {
  PieChart, Pie, Cell, Tooltip,
  ResponsiveContainer
} from "recharts";
import "../styles/userProfile.css";

function UserProfile({ userId, onClose }) {

  const [data, setData] = useState(null);

  useEffect(() => {
    API.get(`get_user_profile.php?user_id=${userId}`)
      .then(res => {
        if (res.data.status) setData(res.data);
      });
  }, [userId]);

  if (!data) return null;

  const overview = data.overview;
  const score = overview.total_score || 0;

  // Medal System
  let medal = "bronze";
  if (data.rank === 1) medal = "gold";
  else if (data.rank <= 3) medal = "silver";

  const COLORS = ["#22c55e", "#ef4444", "#f59e0b"];

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="profile-modal modern" onClick={e => e.stopPropagation()}>

        {/* HEADER */}
        {/* HEADER CARD */}
        <div className="profile-header-card">

          <div className="header-left">
            <div className="avatar-circle">
              {data.user.name.charAt(0)}
            </div>

            <div className="user-info">
              <h2>{data.user.name}</h2>
              <p>Rank #{data.rank}</p>
            </div>
          </div>

          <div className="header-right">
            <div className="medal-icon">
              {medal === "gold" && "🥇"}
              {medal === "silver" && "🥈"}
              {medal === "bronze" && "🥉"}
            </div>

            <div className="score-value">
              <span>Total Score</span>
              <strong><CountUp end={score} duration={1.5} /></strong>
            </div>
          </div>

        </div>


        <div className="profile-body">

          {/* STATS */}
          <div className="stats-grid-modern">
            <div className="mini-card correct">
              <h4>Correct</h4>
              <CountUp end={overview.total_correct || 0} />
            </div>

            <div className="mini-card wrong">
              <h4>Wrong</h4>
              <CountUp end={overview.total_wrong || 0} />
            </div>

            <div className="mini-card unanswered">
              <h4>Unanswered</h4>
              <CountUp end={overview.total_unanswered || 0} />
            </div>

            <div className="mini-card total">
              <h4>Total Questions</h4>
              <CountUp end={overview.total_questions || 0} />
            </div>
          </div>

          {/* PIE */}
          <div className="chart-modern">
            <h3>Answer Distribution</h3>

            <ResponsiveContainer width="100%" height={260}>
              <PieChart>
                <Pie
                  data={data.chart_data}
                  dataKey="value"
                  innerRadius={65}
                  outerRadius={95}
                  paddingAngle={4}
                  label
                >
                  {data.chart_data.map((_, i) => (
                    <Cell key={i} fill={COLORS[i]} />
                  ))}
                </Pie>

                <Tooltip
                  contentStyle={{
                    borderRadius: "12px",
                    border: "none",
                    boxShadow: "0 10px 25px rgba(0,0,0,.15)"
                  }}
                />
              </PieChart>
            </ResponsiveContainer>
          </div>

          {/* CATEGORY BREAKDOWN */}
          <div className="category-section-modern">

            <div className="category-header">
              <h3>📊 Category Performance Breakdown</h3>
            </div>

            <div className="category-table-modern">
              <div className="category-row header">
                <div>Category</div>
                <div>Total</div>
                <div>Correct</div>
                <div>Wrong</div>
                <div>Unanswered</div>
                <div>Accuracy</div>
              </div>

              {data.category_stats.map((cat, i) => (
                <div key={i} className="category-row">

                  <div className="cat-name">
                    {cat.category}
                  </div>

                  <div className="total-box">
                    {cat.total_questions}
                  </div>

                  <div className="badge-stat green">
                    {cat.correct}
                  </div>

                  <div className="badge-stat red">
                    {cat.wrong}
                  </div>

                  <div className="badge-stat yellow">
                    {cat.unanswered}
                  </div>

                  <div className="accuracy-box">
                    <div className="accuracy-bar">
                      <div
                        className="accuracy-fill"
                        style={{ width: `${parseFloat(cat.accuracy)}%` }}
                      />
                    </div>
                    <span>{parseFloat(cat.accuracy).toFixed(1)}%</span>
                  </div>

                </div>
              ))}

            </div>

          </div>


          {/* ACHIEVEMENTS */}
          <div className="achievement-row">
            <div className="achievement-badge">🔥 High Accuracy</div>
            <div className="achievement-badge">⚡ Fast Learner</div>
            <div className="achievement-badge">🏆 Top Performer</div>
          </div>

        </div>

      </div>
    </div>
  );
}

export default UserProfile;
