import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { API } from "../api";
import UserLayout from "../components/UserLayout";
import {
  FaArrowLeft,
  FaArrowRight,
  FaCheckCircle,
  FaRedo,
  FaTimes
} from "react-icons/fa";
import "../styles/quizAttempt.css";
import {
  FaListAlt,
  FaUserCheck,
  FaTimesCircle,
  FaPercentage,
  FaClock
} from "react-icons/fa";


function QuizAttempt() {

  const { id } = useParams();
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user"));

  const [questions, setQuestions] = useState([]);
  const [quizInfo, setQuizInfo] = useState({});
  const [current, setCurrent] = useState(0);
  const [timeLeft, setTimeLeft] = useState(null);
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [result, setResult] = useState(null);
  const [status, setStatus] = useState("COMPLETED");

  const timerRef = useRef(null);

  /* ================= FETCH QUESTIONS ================= */
  useEffect(() => {
    API.get(`get_quiz_userquestions.php?quiz_id=${id}`)
      .then(res => {

        if (Array.isArray(res.data) && res.data.length > 0) {

          const timeLimit = Number(res.data[0].time_limit) || 1;

          setQuestions(res.data);

          setQuizInfo({
            category_id: res.data[0].category_id,
            difficulty: res.data[0].difficulty,
            time_limit: timeLimit
          });

          setTimeLeft(timeLimit * 60);
        }
      });
  }, [id]);

  /* ================= TIMER ================= */
  useEffect(() => {

    if (timeLeft === null || submitted) return;

    timerRef.current = setInterval(() => {

      setTimeLeft(prev => {

        if (prev <= 1) {
          clearInterval(timerRef.current);
          handleSubmit("TIME_OVER");
          return 0;
        }

        return prev - 1;

      });

    }, 1000);

    return () => clearInterval(timerRef.current);

  }, [timeLeft, submitted]);

  const formatTime = () => {
    if (timeLeft === null) return "0:00";
    const mins = Math.floor(timeLeft / 60);
    const secs = timeLeft % 60;
    return `${mins}:${secs < 10 ? "0" : ""}${secs}`;
  };

  const selectOption = (opt) => {
    if (submitted) return;
    setAnswers(prev => ({
      ...prev,
      [questions[current].id]: opt
    }));
  };

  /* ================= RESULT CALCULATION ================= */
  const calculateResult = () => {

    let score = 0;
    let correct = 0;
    let wrong = 0;
    let unanswered = 0;

    const detailedAnswers = [];

    questions.forEach(q => {

      const selected = answers[q.id] || null;
      let isCorrect = false;

      if (!selected) {
        unanswered++;
        score -= 1;
      }
      else if (selected === q.correct_option) {
        correct++;
        score += 2;
        isCorrect = true;
      }
      else {
        wrong++;
        score -= 1;
      }

      detailedAnswers.push({
        question_id: q.id,
        selected: selected,
        correct: q.correct_option,
        is_correct: isCorrect
      });

    });

    const percentage = ((correct / questions.length) * 100).toFixed(1);
    const attended = correct + wrong;

    return {
      total: questions.length,
      attended,
      correct,
      wrong,
      unanswered,
      score,
      percentage,
      detailedAnswers
    };
  };

  const handleSubmit = async (submitStatus = "COMPLETED") => {

    if (submitted) return;

    clearInterval(timerRef.current);

    const resultData = calculateResult();
    const totalTime = quizInfo.time_limit * 60;
    const timeTaken = totalTime - timeLeft;

    setResult({ ...resultData, timeTaken });
    setSubmitted(true);
    setStatus(submitStatus);

    await API.post("save_result.php", {
      user_id: user?.id,
      quiz_id: id,
      category_id: quizInfo.category_id,
      difficulty: quizInfo.difficulty,
      score: resultData.score,
      correct: resultData.correct,
      wrong: resultData.wrong,
      unanswered: resultData.unanswered,
      percentage: resultData.percentage,
      status: submitStatus,
      time_taken: timeTaken,
      answers: resultData.detailedAnswers
    });
  };

  if (!questions.length) {
    return <UserLayout><div style={{ padding: 50 }}>Loading...</div></UserLayout>;
  }

  const q = questions[current];
  const isLast = current === questions.length - 1;

  return (
    <UserLayout>

      <div className="exam-wrapper">

        <div className="exam-card">

          <button className="back-btn" onClick={() => navigate("/quiz-list")}>
            <FaArrowLeft /> Back
          </button>

          <div className="exam-header">
            <h2>{quizInfo.difficulty} Quiz</h2>
            <div className="timer-box">⏱ {formatTime()}</div>
          </div>

          <h4>
            Question {current + 1} / {questions.length}
          </h4>

          <p className="question-text">{q.question}</p>

          {["A", "B", "C", "D"].map(opt => (
            <div
              key={opt}
              className={`option ${answers[q.id] === opt ? "selected" : ""}`}
              onClick={() => selectOption(opt)}
            >
              {opt}. {q["option_" + opt.toLowerCase()]}
            </div>
          ))}

          <div className="nav-buttons">

            <button disabled={current === 0}
              onClick={() => setCurrent(current - 1)}>
              <FaArrowLeft /> Previous
            </button>

            {!isLast ? (
              <button style={{ backgroundColor: "#3b82f6", color: "white" }} onClick={() => setCurrent(current + 1)}>
                Next <FaArrowRight />
              </button>
            ) : (
              <button className="submit-btn"
                onClick={() => handleSubmit()}>
                <FaCheckCircle /> Submit
              </button>
            )}

          </div>

        </div>

        {/* RESULT MODAL */}
        {submitted && result && (
          <div className="result-overlay">

            <div className="result-modal">

              <FaTimes className="close-icon"
                onClick={() => navigate("/quiz-list")} />

              <h2>
                {status === "TIME_OVER"
                  ? "⏰ Time Over"
                  : "🎉 Quiz Completed"}
              </h2>

              <div className="result-grid">

                <div className="result-card total">
                  <FaListAlt className="result-icon" />
                  <div>
                    <h4>{result.total}</h4>
                    <p>Total Questions</p>
                  </div>
                </div>

                <div className="result-card attended">
                  <FaUserCheck className="result-icon" />
                  <div>
                    <h4>{result.attended}</h4>
                    <p>Attended</p>
                  </div>
                </div>

                <div className="result-card correct">
                  <FaCheckCircle className="result-icon" />
                  <div>
                    <h4>{result.correct}</h4>
                    <p>Correct</p>
                  </div>
                </div>

                <div className="result-card wrong">
                  <FaTimesCircle className="result-icon" />
                  <div>
                    <h4>{result.wrong}</h4>
                    <p>Wrong</p>
                  </div>
                </div>

                <div className="result-card percent">
                  <FaPercentage className="result-icon" />
                  <div>
                    <h4>{result.percentage}%</h4>
                    <p>Percentage</p>
                  </div>
                </div>

                <div className="result-card time">
                  <FaClock className="result-icon" />
                  <div>
                    <h4>{result.timeTaken}s</h4>
                    <p>Time Taken</p>
                  </div>
                </div>

              </div>


              <div className="result-actions">
                <button onClick={() => window.location.reload()}>
                  <FaRedo /> Retry
                </button>
                <button className="secondary-btn"
                  onClick={() => navigate("/quiz-list")}>
                  Back to List
                </button>
              </div>

            </div>
          </div>
        )}

      </div>
    </UserLayout>
  );
}

export default QuizAttempt;
