import React, { useEffect, useState } from "react";
import { API } from "../api";
import {
  FaMedal,
  FaCheckCircle,
  FaTimesCircle,
  FaQuestionCircle
} from "react-icons/fa";
import "../styles/leaderboard.css";

function TopLeaderboard() {

  const [leaders, setLeaders] = useState([]);

  useEffect(() => {
    API.get("get_top_leaderboard.php")
      .then(res => {
        setLeaders(Array.isArray(res.data) ? res.data : []);
      });
  }, []);

  const getRankDisplay = (index) => {
    if (index === 0) return "🥇";
    if (index === 1) return "🥈";
    if (index === 2) return "🥉";
    return `#${index + 1}`;
  };

  return (
    <div className="leaderboard-card">

      <h3 className="leaderboard-title">
        🏆 Top 5 Leaderboard
      </h3>

      <div className="leaderboard-list">

        {leaders.slice(0,5).map((user, index) => (
          <div key={user.id} className="leaderboard-row">

            {/* LEFT : RANK */}
            <div className="rank-section">
              {getRankDisplay(index)}
            </div>

            {/* PROFILE */}
            <div className="profile-section">
              <div className="avatar">
                {user.name.charAt(0)}
              </div>

              <div className="profile-info">
                <div className="name">
                  {user.name}
                </div>
                <div className="subtitle">
                  Rank #{user.rank}
                </div>
              </div>
            </div>

            {/* MIDDLE STATS */}
            <div className="stats-section">

              <div className="stat total">
                <FaQuestionCircle />
                {user.total_questions}
              </div>

              <div className="stat correct">
                <FaCheckCircle />
                {user.total_correct}
              </div>

              <div className="stat wrong">
                <FaTimesCircle />
                {user.total_wrong}
              </div>

            </div>

            {/* RIGHT SCORE */}
            <div className="score-section">
              <span>Total Score</span>
              <strong>{user.total_score}</strong>
            </div>

          </div>
        ))}

      </div>

    </div>
  );
}

export default TopLeaderboard;
