import React, { useEffect, useState } from "react";
import { API } from "../api";
import AdminLayout from "../components/AdminLayout";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid
} from "recharts";
import { Cell } from "recharts";
import { FaCheckCircle, FaTimesCircle, FaClipboardList } from "react-icons/fa";


import "../styles/admindashboard.css";
function AdminDashboard() {

  const [data, setData] = useState({
    top5Chart: [],
    allUsers: []
  });

  useEffect(() => {
    API.get("get_admin_dashboard.php")
      .then(res => {
        setData({
          top5Chart: res.data.top5Chart || [],
          allUsers: res.data.allUsers || []
        });
      });
  }, []);


  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {

      const totalQ = payload.find(p => p.dataKey === "total_questions")?.value || 0;
      const correct = payload.find(p => p.dataKey === "total_correct")?.value || 0;
      const wrong = payload.find(p => p.dataKey === "total_wrong")?.value || 0;

      return (
        <div className="custom-tooltip">
          <h4>{label}</h4>

          <div className="tooltip-row blue">
            <FaClipboardList />
            <span>Total Questions</span>
            <strong>{totalQ}</strong>
          </div>

          <div className="tooltip-row green">
            <FaCheckCircle />
            <span>Correct</span>
            <strong>{correct}</strong>
          </div>

          <div className="tooltip-row red">
            <FaTimesCircle />
            <span>Wrong</span>
            <strong>{wrong}</strong>
          </div>

        </div>
      );
    }

    return null;
  };


  return (
    <AdminLayout>

      <div className="dashboard-grid">

        {/* ===== LEFT : TOP 5 COLUMN CHART ===== */}
        <div className="dashboard-card">

          <h3>📊 Top 5 Users Performance</h3>

          <ResponsiveContainer width="100%" height={200}>
            <BarChart data={data.top5Chart}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip content={<CustomTooltip />} cursor={{ fill: "rgba(99,102,241,0.08)" }} />

              <Bar
                dataKey="total_questions"
                fill="#6366f1"
                radius={[6, 6, 0, 0]}
                animationDuration={800}
              />

              <Bar
                dataKey="total_correct"
                fill="#22c55e"
                radius={[6, 6, 0, 0]}
                animationDuration={1000}
              />

              <Bar
                dataKey="total_wrong"
                fill="#ef4444"
                radius={[6, 6, 0, 0]}
                animationDuration={1200}
              />

            </BarChart>
          </ResponsiveContainer>

        </div>

        {/* ===== RIGHT : USER LIST ===== */}
        <div className="dashboard-card">

          <h3>🏆 All User Ranking List</h3>
          <div className="user-list-scroll">


            {data.allUsers.map((user, index) => (

              <div key={user.id} className="user-row">

                {/* LEFT */}
                <div className="user-left">

                  <div className="user-rank">
                    {index === 0 ? "🥇" :
                      index === 1 ? "🥈" :
                        index === 2 ? "🥉" :
                          `#${user.rank}`}
                  </div>

                  <div className="user-avatar">
                    {user.name.charAt(0)}
                  </div>

                  <div className="user-info">
                    <div className="user-name">{user.name}</div>
                    <div className="user-rank-text">Rank #{user.rank}</div>
                  </div>

                </div>

                {/* MIDDLE */}
                <div className="user-stats">
                  <span>Q:{user.total_questions}</span>
                  <span className="correct">✔ {user.total_correct}</span>
                  <span className="wrong">✖ {user.total_wrong}</span>
                </div>

                {/* RIGHT */}
                <div className="user-score">
                  {user.total_score}
                </div>

              </div>

            ))}

          </div>

        </div>

      </div>

    </AdminLayout>
  );
}


export default AdminDashboard;
