import React, { useEffect, useState } from "react";
import { API } from "../api";
import UserLayout from "../components/UserLayout";
import TopLeaderboard from "../pages/TopLeaderboard";

import {
  FaEye,
  FaLayerGroup,
  FaChartLine,
  FaCheckCircle,
  FaTimesCircle, FaChartPie, FaHistory
} from "react-icons/fa";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip
} from "recharts";
import "../styles/userDashboard.css";

function UserDashboard() {

  const user = JSON.parse(localStorage.getItem("user"));

  const [totalAttempts, setTotalAttempts] = useState(0);
  const [categories, setCategories] = useState([]);
  const [recent, setRecent] = useState([]);

  const [filterCategory, setFilterCategory] = useState("");
  const [filterDifficulty, setFilterDifficulty] = useState("");
  const [details, setDetails] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const openDetails = (resultId) => {

    API.get(`get_attempt_details.php?result_id=${resultId}`)
      .then(res => {
        setDetails(Array.isArray(res.data) ? res.data : []);
        setShowModal(true);
      });

  };


  /* ================= LOAD CHART ================= */
  useEffect(() => {
    if (!user?.id) return;

    API.get(`get_attempt_chart.php?user_id=${user.id}`)
      .then(res => {
        setTotalAttempts(res.data?.total_attempts || 0);
        setCategories(
          Array.isArray(res.data?.categories)
            ? res.data.categories
            : []
        );
      });

  }, [user?.id]);

  /* ================= LOAD RECENT (WITH FILTER) ================= */
  useEffect(() => {

    if (!user?.id) return;

    API.get(
      `get_recent_attempts.php?user_id=${user.id}&category=${filterCategory}&difficulty=${filterDifficulty}`
    )
      .then(res => {
        setRecent(Array.isArray(res.data) ? res.data : []);
      });

  }, [user?.id, filterCategory, filterDifficulty]);

  const COLORS = [
    "#6366f1",
    "#22c55e",
    "#f59e0b",
    "#ef4444",
    "#14b8a6",
    "#8b5cf6"
  ];

  const total = categories.reduce(
    (sum, item) => sum + Number(item.attempts),
    0
  );

  return (
    <UserLayout>

      <div className="dashboard-grid">

        {/* ===== LEFT : DONUT ===== */}
        <div className="dashboard-card">

          <h3 className="dashboard-title">
            <FaChartPie className="title-icon" />
            Category Wise Attempts
          </h3>


          {/* ================= DONUT SECTION ================= */}
          <div className="dashboard-content">

            {/* Donut */}
            <div className="donut-section">

              <PieChart width={200} height={200}>
                <Pie
                  data={categories}
                  dataKey="attempts"
                  nameKey="category"
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={3}
                >
                  {categories.map((entry, index) => (
                    <Cell
                      key={index}
                      fill={COLORS[index % COLORS.length]}
                    />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>

              <div className="donut-center">
                <h2>{totalAttempts}</h2>
                <span>Total Attempts</span>
              </div>

            </div>

            {/* ================= LEGEND + PROGRESS ================= */}
            <div className="performance-section">

              {categories.map((item, index) => {

                const percent = total
                  ? ((item.attempts / total) * 100).toFixed(0)
                  : 0;

                return (
                  <div
                    key={index}
                    className="performance-item"
                  >

                    <div className="performance-header">
                      <div className="left">

                        <span
                          className="color-dot"
                          style={{
                            background:
                              COLORS[index % COLORS.length]
                          }}
                        />

                        <span>{item.category}</span>

                      </div>

                      <span>{percent}%</span>
                    </div>

                    <div className="progress-bar">
                      <div
                        className="progress-fill"
                        style={{
                          width: `${percent}%`,
                          background:
                            COLORS[index % COLORS.length]
                        }}
                      />
                    </div>

                  </div>
                );
              })}

            </div>

          </div>

        </div>

        {/* ===== RIGHT : RECENT ===== */}
        <div className="recent-card">

          {/* Heading */}
          <h3 className="recent-heading">
            <FaHistory className="heading-icon" />
            Recent Attempts
          </h3>


          {/* Filters - Next Line */}
          <div className="recent-filters">
            <select
              value={filterCategory}
              onChange={e => setFilterCategory(e.target.value)}
            >
              <option value="">All Categories</option>
              {categories.map((c, i) => (
                <option key={i} value={c.category}>
                  {c.category}
                </option>
              ))}
            </select>

            <select
              value={filterDifficulty}
              onChange={e => setFilterDifficulty(e.target.value)}
            >
              <option value="">All Difficulty</option>
              <option value="Easy">Easy</option>
              <option value="Medium">Medium</option>
              <option value="Hard">Hard</option>
            </select>
          </div>

          {/* Data List */}
          <div className="recent-list">
            {recent.length === 0 ? (
              <div className="no-data">No Attempts</div>
            ) : (
              recent.map((item, index) => (
                <div key={index} className="recent-row">

                  {/* LEFT SIDE */}
                  <div className="recent-left">
                    <div className="quiz-title">
                      <FaLayerGroup className="icon primary" />
                      {item.title}
                    </div>

                    <div className="quiz-meta">
                      {item.category} • {item.difficulty}
                    </div>

                    <div className="quiz-stats">

                      <div className="stat-item">
                        <FaChartLine className="icon stat" />
                        <span>Total: {item.total_questions}</span>
                      </div>

                      <div className="stat-item correct">
                        <FaCheckCircle />
                        <span>{item.correct}</span>
                      </div>

                      <div className="stat-item wrong">
                        <FaTimesCircle />
                        <span>{item.wrong}</span>
                      </div>

                    </div>
                  </div>

                  {/* RIGHT SIDE */}
                  <div className="recent-right">

                    <div className="percent-badge">
                      {item.percentage}%
                    </div>

                    <button
                      className="view-btn"
                      onClick={() => openDetails(item.id)}
                    >
                      <FaEye /> View
                    </button>

                  </div>

                </div>
              ))
            )}
          </div>

          {showModal && (
            <div className="modal-overlay">

              <div className="modal-content">

                {/* ===== HEADER ===== */}
                <div className="modal-header">
                  <h3>Attempt Details</h3>

                  <span
                    className="modal-close"
                    onClick={() => setShowModal(false)}
                  >
                    ✕
                  </span>
                </div>

                {/* ===== QUESTIONS ===== */}
                <div className="modal-questions">

                  {details.length === 0 ? (
                    <div className="no-data">No Question Details</div>
                  ) : (
                    details.map((q, i) => {

                      return (
                        <div key={i} className="question-block">

                          <div className="question-title">
                            {i + 1}. {q.question}
                          </div>

                          {["A", "B", "C", "D"].map(opt => {

                            const optionText = q[`option_${opt.toLowerCase()}`];

                            const isSelected = q.selected_option === opt;
                            const isCorrect = q.correct_option === opt;

                            return (
                              <div
                                key={opt}
                                className={`option 
                        ${isCorrect ? "correct" : ""} 
                        ${isSelected && !isCorrect ? "wrong" : ""}
                      `}
                              >
                                {opt}. {optionText}

                                {isCorrect && (
                                  <span className="option-badge correct-badge">
                                    Correct Answer
                                  </span>
                                )}

                                {isSelected && !isCorrect && (
                                  <span className="option-badge wrong-badge">
                                    Your Answer
                                  </span>
                                )}
                              </div>
                            );
                          })}

                        </div>
                      );
                    })
                  )}

                </div>

              </div>

            </div>
          )}



        </div>







      </div>

      {/* ===== LEADERBOARD SECTION ===== */}
      <div className="leaderboard-section">
        <TopLeaderboard />
      </div>

    </UserLayout>
  );
}

export default UserDashboard;
