import React, { useEffect, useState } from "react";
import { API } from "../api";
import UserLayout from "../components/UserLayout";
import { FaEye, FaFilter } from "react-icons/fa";
import "../styles/userreport.css";

function UserReport() {

    const storedUser = JSON.parse(localStorage.getItem("user"));

    const [userData, setUserData] = useState(null);

    const [filtersData, setFiltersData] = useState({
        categories: [],
        difficulties: []
    });

    const [filters, setFilters] = useState({
        user_id: storedUser?.id || "",
        category_id: "",
        difficulty: ""
    });

    const [modalData, setModalData] = useState([]);
    const [showModal, setShowModal] = useState(false);

    useEffect(() => {

        // Get category + difficulty filter data
        API.get("get_report_filters.php")
            .then(res => setFiltersData(res.data));

        fetchData();

    }, []);

    const fetchData = () => {

        API.get("get_detailed_report.php", {
            params: {
                user_id: storedUser?.id,
                category_id: filters.category_id,
                difficulty: filters.difficulty
            }
        })
        .then(res => {
            // API returns array → take first user
            if (res.data.length > 0) {
                setUserData(res.data[0]);
            } else {
                setUserData(null);
            }
        });

    };

    const openModal = (result_id) => {
        API.get("get_attempt_details.php", { params: { result_id } })
            .then(res => {
                setModalData(res.data);
                setShowModal(true);
            });
    };

    if (!storedUser) {
        return <div>User not logged in</div>;
    }

    return (
        <UserLayout>

            <div className="report-container">

                {/* ================= FILTER BAR ================= */}
                <div className="filter-bar">

                    <div className="filter-title">
                        <FaFilter /> Filter Attempts
                    </div>

                    <div className="filter-controls">

                        <select
                            onChange={e =>
                                setFilters({ ...filters, category_id: e.target.value })
                            }
                        >
                            <option value="">All Categories</option>
                            {filtersData.categories.map(c => (
                                <option key={c.id} value={c.id}>{c.name}</option>
                            ))}
                        </select>

                        <select
                            onChange={e =>
                                setFilters({ ...filters, difficulty: e.target.value })
                            }
                        >
                            <option value="">All Difficulty</option>
                            {filtersData.difficulties.map(d => (
                                <option key={d}>{d}</option>
                            ))}
                        </select>

                        <button onClick={fetchData}>Apply</button>

                    </div>
                </div>

                {/* ================= USER CARD ================= */}

                {userData && (
                    <div className="user-card">

                        <div className="user-header">

                            <div className="user-left">
                                <div className="user-avatar">
                                    {userData.name.charAt(0)}
                                </div>

                                <div>
                                    <h2>{userData.name}</h2>
                                    <p>
                                        🔥 Most Attempt:
                                        <strong> {userData.most_quiz}</strong>
                                        ({userData.most_attempts} Times)
                                    </p>
                                </div>
                            </div>

                            {/* <div className="user-summary">
                                <span className="rank-badge">
                                    🏆 Rank #{userData.rank}
                                </span>
                                <div className="total-score">
                                    💯 {userData.total_score}
                                </div>
                            </div> */}

                        </div>

                        <div className="attempt-list">

                            {userData.attempts.map(a => (
                                <div key={a.result_id} className="attempt-row">

                                    <div className="attempt-title">
                                        {a.title} <span>({a.difficulty})</span>
                                    </div>

                                    <div className="attempt-stats">
                                        <span>Q: {a.total_questions}</span>
                                        <span className="green">✔ {a.correct}</span>
                                        <span className="red">✖ {a.wrong}</span>
                                        <span className="gray">? {a.unanswered}</span>
                                        <span className="score">Score: {a.score}</span>
                                    </div>

                                    <button onClick={() => openModal(a.result_id)}>
                                        <FaEye /> View
                                    </button>

                                </div>
                            ))}

                        </div>

                    </div>
                )}

            </div>

            {/* ================= MODAL ================= */}
            {showModal && (
                <div className="modal-overlay">
                    <div className="modal-box">

                        <div className="modal-header">
                            <h3>Attempt Details</h3>
                            <span onClick={() => setShowModal(false)}>✕</span>
                        </div>

                        {modalData.map((q, i) => {

                            const options = [
                                { key: "A", value: q.option_a },
                                { key: "B", value: q.option_b },
                                { key: "C", value: q.option_c },
                                { key: "D", value: q.option_d }
                            ];

                            return (
                                <div key={i} className="question-card">

                                    <div className="question-title">
                                        {i + 1}. {q.question}
                                    </div>

                                    <div className="options-list">
                                        {options.map(opt => {

                                            let className = "option-item";

                                            if (opt.key === q.correct_option) {
                                                className += " correct-option";
                                            }

                                            if (opt.key === q.selected_option && opt.key !== q.correct_option) {
                                                className += " wrong-option";
                                            }

                                            if (opt.key === q.selected_option && opt.key === q.correct_option) {
                                                className += " selected-correct";
                                            }

                                            return (
                                                <div key={opt.key} className={className}>
                                                    <strong>{opt.key}.</strong> {opt.value}
                                                </div>
                                            );
                                        })}
                                    </div>

                                </div>
                            );
                        })}

                    </div>
                </div>
            )}

        </UserLayout>
    );
}

export default UserReport;
