import React, { useEffect, useState } from "react";
import { API } from "../api";
import AdminLayout from "../components/AdminLayout";
import DataTable from "react-data-table-component";
import {
  FaPlusCircle,
  FaList,
  FaEdit,
  FaTrash
} from "react-icons/fa";
import "../styles/question.css";

function QuestionManagement() {

  const [activeTab, setActiveTab] = useState("add");
  const [questions, setQuestions] = useState([]);
  const [categories, setCategories] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [search, setSearch] = useState("");

  const [filter, setFilter] = useState({
    category: "",
    difficulty: ""
  });

  const handleToggleStatus = async (row) => {

    const confirmAction = window.confirm(
      row.status == 1
        ? "Make this question Inactive?"
        : "Make this question Active?"
    );

    if (!confirmAction) return;

    await API.post("toggle_question_status.php", {
      id: row.id,
      status: row.status
    });

    fetchQuestions();
  };


  const [form, setForm] = useState({
    category_id: "",
    difficulty: "Easy",
    question: "",
    option_a: "",
    option_b: "",
    option_c: "",
    option_d: "",
    correct_option: "A"
  });

  useEffect(() => {
    fetchQuestions();
    fetchCategories();
  }, []);

  const fetchQuestions = async () => {
    const res = await API.get("get_questions.php");
    setQuestions(res.data || []);
  };

  const fetchCategories = async () => {
    const res = await API.get("get_categories.php");
    setCategories(res.data || []);
  };

  /* ================= ADD / UPDATE ================= */

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.category_id) {
      alert("Select category");
      return;
    }

    if (editingId) {
      await API.post("update_question.php", {
        id: editingId,
        ...form
      });
    } else {
      await API.post("add_question.php", form);
    }

    resetForm();
    fetchQuestions();
    setActiveTab("list");
  };

  const resetForm = () => {
    setForm({
      category_id: "",
      difficulty: "Easy",
      question: "",
      option_a: "",
      option_b: "",
      option_c: "",
      option_d: "",
      correct_option: "A"
    });
    setEditingId(null);
  };

  /* ================= EDIT ================= */

  const handleEdit = (q) => {
    setActiveTab("add");
    setEditingId(q.id);

    setForm({
      category_id: q.category_id,
      difficulty: q.difficulty,
      question: q.question,
      option_a: q.option_a,
      option_b: q.option_b,
      option_c: q.option_c,
      option_d: q.option_d,
      correct_option: q.correct_option
    });
  };

  /* ================= DELETE ================= */

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this question?")) return;
    await API.post("delete_question.php", { id });
    fetchQuestions();
  };

  /* ================= FILTER + SEARCH ================= */

  const filteredQuestions = questions.filter((q) => {
    return (
      (filter.category ? String(q.category_id) === filter.category : true) &&
      (filter.difficulty ? q.difficulty === filter.difficulty : true) &&
      (search
        ? q.question.toLowerCase().includes(search.toLowerCase())
        : true)
    );
  });

  /* ================= DATATABLE COLUMNS ================= */

  const columns = [
    {
      name: "Question",
      selector: row => row.question,
      wrap: true
    },
    {
      name: "Category",
      selector: row => row.category_name
    },
    {
      name: "Difficulty",
      cell: row => (
        <span className={`badge ${row.difficulty.toLowerCase()}`}>
          {row.difficulty}
        </span>
      )
    },
    {
      name: "Status",
      cell: row => (
        <span
          className={`status-badge ${row.status == 1 ? "active-status" : "inactive-status"}`}
          onClick={() => handleToggleStatus(row)}
        >
          {row.status == 1 ? "Active" : "Inactive"}
        </span>
      )
    },
    {
      name: "Correct",
      selector: row => row.correct_option
    },
    {
      name: "Action",
      cell: row => (
        <>
          <FaEdit
            className="table-icon edit"
            onClick={() => handleEdit(row)}
          />
          <FaTrash
            className="table-icon delete"
            onClick={() => handleDelete(row.id)}
          />
        </>
      )
    }
  ];


  return (
    <AdminLayout>

      <div className="question-wrapper">

        <h2 className="page-title">Question Management</h2>

        {/* TABS */}
        <div className="tab-container">
          <button
            className={activeTab === "add" ? "tab active" : "tab"}
            onClick={() => setActiveTab("add")}
          >
            <FaPlusCircle /> Add Question
          </button>

          <button
            className={activeTab === "list" ? "tab active" : "tab"}
            onClick={() => setActiveTab("list")}
          >
            <FaList /> Question List
          </button>
        </div>

        {/* ADD TAB */}
        {activeTab === "add" && (
          <div className="card gradient-card">
            <form onSubmit={handleSubmit}>

              {/* CATEGORY + DIFFICULTY SAME LINE */}
              <div className="form-top-row">
                <select
                  value={form.category_id}
                  onChange={(e) => setForm({ ...form, category_id: e.target.value })}
                  required
                >
                  <option value="">Select Category</option>
                  {categories.map(cat => (
                    <option key={cat.id} value={cat.id}>
                      {cat.name}
                    </option>
                  ))}
                </select>

                <select
                  value={form.difficulty}
                  onChange={(e) => setForm({ ...form, difficulty: e.target.value })}
                >
                  <option>Easy</option>
                  <option>Medium</option>
                  <option>Hard</option>
                </select>
              </div>

              <textarea
                placeholder="Enter Question"
                value={form.question}
                onChange={(e) => setForm({ ...form, question: e.target.value })}
                required
              />

              <div className="option-grid">
                <input placeholder="Option A"
                  value={form.option_a}
                  onChange={(e) => setForm({ ...form, option_a: e.target.value })}
                  required />
                <input placeholder="Option B"
                  value={form.option_b}
                  onChange={(e) => setForm({ ...form, option_b: e.target.value })}
                  required />
                <input placeholder="Option C"
                  value={form.option_c}
                  onChange={(e) => setForm({ ...form, option_c: e.target.value })}
                  required />
                <input placeholder="Option D"
                  value={form.option_d}
                  onChange={(e) => setForm({ ...form, option_d: e.target.value })}
                  required />
              </div>

              <select
                value={form.correct_option}
                onChange={(e) => setForm({ ...form, correct_option: e.target.value })}
              >
                <option value="A">Correct: A</option>
                <option value="B">Correct: B</option>
                <option value="C">Correct: C</option>
                <option value="D">Correct: D</option>
              </select>

              <button type="submit" className="primary-btn">
                {editingId ? "Update Question" : "Add Question"}
              </button>

            </form>
          </div>
        )}

        {/* LIST TAB */}
        {activeTab === "list" && (
          <div className="card">

            {/* FILTER ROW */}
            <div className="filter-bar">

              <select
                value={filter.category}
                onChange={(e) => setFilter({ ...filter, category: e.target.value })}
              >
                <option value="">All Categories</option>
                {categories.map(cat => (
                  <option key={cat.id} value={cat.id}>
                    {cat.name}
                  </option>
                ))}
              </select>

              <select
                value={filter.difficulty}
                onChange={(e) => setFilter({ ...filter, difficulty: e.target.value })}
              >
                <option value="">All Difficulty</option>
                <option>Easy</option>
                <option>Medium</option>
                <option>Hard</option>
              </select>

              <input
                type="text"
                placeholder="Search question..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />

            </div>

            <DataTable
              columns={columns}
              data={filteredQuestions}
              pagination
              highlightOnHover
              striped
              responsive
            />

          </div>
        )}

      </div>

    </AdminLayout>
  );
}

export default QuestionManagement;
