import { Routes, Route } from "react-router-dom";
import Login from "./pages/Login";
import Register from "./pages/Register";
import UserDashboard from "./pages/UserDashboard";
import AdminDashboard from "./pages/AdminDashboard";
import QuestionManagement from "./pages/QuestionManagement";
import QuizManagement from "./pages/QuizManagement";
import QuizListing from "./pages/QuizListing";
import QuizAttempt from "./pages/QuizAttempt";
import UserProfile from "./pages/UserProfile";
import AddCategory from "./pages/Addcategory";
import TopLeaderboard from "./pages/TopLeaderboard";
import Adminreport from "./pages/Adminreport";
import UserReport from "./pages/UserReport";






function App() {
  return (
    <Routes>
      <Route path="/" element={<Login />} />
      <Route path="/register" element={<Register />} />
      <Route path="/user-dashboard" element={<UserDashboard />} />
      <Route path="/admin-dashboard" element={<AdminDashboard />} />
      <Route path="/question-management" element={<QuestionManagement />} />
      <Route path="/quiz-management" element={<QuizManagement />} />
      <Route path="/quiz-list" element={< QuizListing />} />
      {/* <Route path="/quiz-attempt" element={< QuizAttempt />} /> */}
      <Route path="/quiz-attempt/:id" element={<QuizAttempt />} />
      <Route path="/profile" element={< UserProfile />} />
      <Route path="/add-category" element={< AddCategory />} />
      <Route path="/top-leaderboard" element={< TopLeaderboard/>} />
      <Route path="/admin-reports" element={< Adminreport/>} />
      <Route path="/user-reports" element={< UserReport/>} />








    </Routes>
  )
}

export default App;
