import React, { useEffect, useState } from "react";
import { API } from "../api";
import UserLayout from "../components/UserLayout";
import { FaPlayCircle,FaLayerGroup } from "react-icons/fa";
import { useNavigate } from "react-router-dom";
import "../styles/quizListing.css";

function QuizListing() {

    const navigate = useNavigate();

    const [quizzes, setQuizzes] = useState([]);
    const [categories, setCategories] = useState([]);
    const [loading, setLoading] = useState(false);

    const [filters, setFilters] = useState({
        category: "",
        difficulty: "",
        search: ""
    });

    useEffect(() => {
        fetchCategories();
    }, []);

    useEffect(() => {
        fetchQuizzes();
    }, [filters]);

    const fetchQuizzes = async () => {
        try {
            setLoading(true);
            const res = await API.get("get_userquizlist.php", {
                params: filters
            });
            setQuizzes(res.data || []);
        } catch {
            setQuizzes([]);
        } finally {
            setLoading(false);
        }
    };

    const fetchCategories = async () => {
        const res = await API.get("get_categories.php");
        setCategories(res.data || []);
    };

    return (
        <UserLayout>

            <div className="quiz-list-wrapper">

                <div className="quiz-header-top">
                    <h2>🎯 Explore Quizzes</h2>
                    <p>Challenge yourself and improve your knowledge</p>
                </div>

                {/* FILTERS */}
                <div className="filter-card">

                    <input
                        placeholder="Search quiz..."
                        value={filters.search}
                        onChange={(e) => setFilters({ ...filters, search: e.target.value })}
                    />

                    <select
                        value={filters.category}
                        onChange={(e) => setFilters({ ...filters, category: e.target.value })}
                    >
                        <option value="">All Categories</option>
                        {categories.map(cat => (
                            <option key={cat.id} value={cat.id}>
                                {cat.name}
                            </option>
                        ))}
                    </select>

                    <select
                        value={filters.difficulty}
                        onChange={(e) => setFilters({ ...filters, difficulty: e.target.value })}
                    >
                        <option value="">All Difficulty</option>
                        <option value="Easy">Easy</option>
                        <option value="Medium">Medium</option>
                        <option value="Hard">Hard</option>
                    </select>

                </div>

                {/* GRID */}
                {/* GRID */}
                <div className="quiz-grid-wrapper">
                    <div className="quiz-grid">
                        {loading ? (
                            <div className="no-data">Loading...</div>
                        ) : quizzes.length > 0 ? (
                            quizzes.map(q => (
                                <div key={q.id} className="quiz-card-modern">

                                    <div className="quiz-card-content">

                                        <h3 className="quiz-title"><FaLayerGroup className="icon primary" />{q.title}</h3>

                                        <div className="quiz-meta">
                                            <span className="category-chip">{q.category}</span>
                                            <span className={`difficulty-chip ${q.difficulty.toLowerCase()}`}>
                                                {q.difficulty}
                                            </span>
                                        </div>

                                        <div className="quiz-stats">
                                            <span>📝 {q.total_questions} Questions</span>
                                            <span>⏱ {q.time_limit} mins</span>
                                        </div>

                                        <button
                                            className={`start-btn-modern ${Number(q.total_questions) === 0 ? "disabled-btn" : ""
                                                }`}
                                            disabled={Number(q.total_questions) === 0}
                                            onClick={() => {
                                                if (Number(q.total_questions) > 0) {
                                                    navigate(`/quiz-attempt/${q.id}`);
                                                }
                                            }}
                                        >
                                            <FaPlayCircle />
                                            {Number(q.total_questions) === 0
                                                ? "No Questions Available"
                                                : "Start Quiz"}
                                        </button>


                                    </div>

                                </div>
                            ))
                        ) : (
                            <div className="no-data">No quizzes found</div>
                        )}
                    </div>
                </div>


            </div>

        </UserLayout>
    );
}

export default QuizListing;
