import React, { useEffect, useState } from "react";
import { API } from "../api";
import AdminLayout from "../components/AdminLayout";
import { FaEdit, FaTrash } from "react-icons/fa";
import "../styles/category.css";

function AddCategory() {

  const [categories, setCategories] = useState([]);
  const [name, setName] = useState("");
  const [editId, setEditId] = useState(null);

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    const res = await API.get("get_categories.php");
    setCategories(res.data);
  };

  const handleSubmit = async () => {
    if (!name.trim()) return alert("Enter category name");

    if (editId) {
      await API.post("update_category.php", { id: editId, name });
    } else {
      await API.post("add_category.php", { name });
    }

    setName("");
    setEditId(null);
    fetchCategories();
  };

  const handleEdit = (cat) => {
    setName(cat.name);
    setEditId(cat.id);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Delete this category?")) return;
    await API.post("delete_category.php", { id });
    fetchCategories();
  };

  /* ===== STATUS TOGGLE ===== */

  const handleStatusChange = async (cat) => {

    if (cat.status === "0" || cat.status === 0) {
      const confirmActive = window.confirm(
        "Are you sure to activate this category?"
      );
      if (!confirmActive) return;

      await API.post("update_status.php", {
        id: cat.id,
        status: 1
      });

    }

    //  else {
    //   const confirmInactive = window.confirm(
    //     "Are you sure to deactivate this category?"
    //   );
    //   if (!confirmInactive) return;

    //   await API.post("update_status.php", {
    //     id: cat.id,
    //     status: 0
    //   });
    // }

    fetchCategories();
  };

  return (
    <AdminLayout>

      <div className="category-container">

        <h2>Add Category</h2>

        <div className="add-box">
          <input
            type="text"
            placeholder="Enter category name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <button onClick={handleSubmit}>
            {editId ? "Update" : "Add"}
          </button>
        </div>

        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>

            <tbody>
              {categories.map((cat) => (
                <tr key={cat.id}>
                  <td>{cat.id}</td>
                  <td>{cat.name}</td>

                  <td>
                    <span
                      className={
                        cat.status === '1'
                          ? "status-active"
                          : "status-inactive"
                      }
                      onClick={() => handleStatusChange(cat)}
                      style={{ cursor: "pointer" }}
                    >
                      {cat.status === '1' ? "Active" : "Inactive"}
                    </span>
                  </td>

                  <td>
                    <FaEdit
                      className="icon edit"
                      onClick={() => handleEdit(cat)}
                    />
                    <FaTrash
                      className="icon delete"
                      onClick={() => handleDelete(cat.id)}
                    />
                  </td>

                </tr>
              ))}
            </tbody>
          </table>
        </div>

      </div>

    </AdminLayout>
  );
}

export default AddCategory;
